/** A person's due-total for a period as shown: the one fixed when it was (soft-)closed (0.00 for a person added since), else
 *  their live one. */
export function shownPersonDueTotal(period: Period, personId: number, liveCents: bigint): string {
  return isFixed(period) ? (period.closedPeople[String(personId)] ?? '0.00') : twoDecimals(liveCents);
}

/** A person's carried figure for a period as shown: the one fixed when it was (soft-)closed (0.00 for a person added
 *  since), else their live one. */
export function shownPersonCarried(period: Period, personId: number, liveCents: bigint): string {
  return isFixed(period) ? (period.closedCarried[String(personId)] ?? '0.00') : twoDecimals(liveCents);
}

/** A period's due-total as shown: the one fixed when it was (soft-)closed, else its live one. */
export function shownDueTotal(period: Period, liveCents: bigint): string {
  return isFixed(period) && period.closedTotal !== null ? period.closedTotal : twoDecimals(liveCents);
}
import { Fragment } from 'react';
import { PersonColumnHeaders, PersonColumns } from '../../slots/defs/personRow';
import { usePeople } from '../people/people';
import type { Person } from '../people/people';
import { useRates } from '../rates/rates';
import { useFloorCents } from '../settings/settings';
import { useClaims, useLate } from '../claims/claims';
import {
  personPeriodCarriedCents,
  personPeriodDueCents,
  shownPersonCarried,
  shownPersonDueTotal,
  usePeriods,
} from './periods';
import { Fig } from '../locale/Fig';

function PeriodHeaders({ sheet }: { sheet: string; user: string }) {
  const { data: periods = [] } = usePeriods(sheet);
  return (
    <>
      {periods.map((p) => (
        <Fragment key={p.name}>
          <th>{p.name} due</th>
          <th>{p.name} carried</th>
        </Fragment>
      ))}
    </>
  );
}

// Per period on the sheet, the person's due-total for it and their carried figure (see personPeriodCarriedCents): the due now of their claims whose due-by falls in it that counted at its end,
// both fixed for everyone on the sheet when the period is (soft-)closed (0.00 for a person added since) and live
// again once it is reopened. The period's own due-total is the sum of the due-totals.
function PersonPeriods({ sheet, person }: { sheet: string; user: string; person: Person }) {
  const { data: periods = [] } = usePeriods(sheet);
  const { data: claims = [] } = useClaims(sheet);
  const { data: people = [] } = usePeople(sheet);
  const { data: rates = [] } = useRates(sheet);
  const floor = useFloorCents(sheet);
  const late = useLate(sheet);

  const totals = personPeriodDueCents(periods, claims, people, rates, floor, late);
  const carried = personPeriodCarriedCents(periods, claims, people, rates, floor, late);

  return (
    <>
      {periods.map((p) => (
        <Fragment key={p.name}>
          <td data-testid={`person-period-${p.name}-due-total`}>
            <Fig>{shownPersonDueTotal(p, person.id, totals.get(p.name)?.get(person.id) ?? 0n)}</Fig>
          </td>
          <td data-testid={`person-period-${p.name}-carried`}>
            <Fig>{shownPersonCarried(p, person.id, carried.get(p.name)?.get(person.id) ?? 0n)}</Fig>
          </td>
        </Fragment>
      ))}
    </>
  );
}

export const contributions = [
  PersonColumnHeaders.fill({ order: 15, Component: PeriodHeaders }),
  PersonColumns.fill({ order: 15, Component: PersonPeriods }),
];
import { useState, type FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { byUser } from '../session/session';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { peopleKey, peoplePath } from './people';
import type { Person } from './people';

type Imported = { added: number; updated: number; people: Person[] };

// The import box: lines of name,grade,terms,contact (the last two may be absent or blank), in order. A line whose name
// is a name or alias of a person on the sheet updates them as the person form would (terms and contact only when given);
// any other adds a person. The server checks every line by the form's rules first (a person or contact repeated within
// the import too), so a refusal changes no one. Shows how many were added and how many updated.
function ImportPeople({ sheet, user }: { sheet: string; user: string }) {
  const queryClient = useQueryClient();
  const [text, setText] = useState('');
  const importing = useMutation({
    mutationFn: (body: string) => postJson<Imported>(byUser(`${peoplePath(sheet)}/import`, user), { text: body }),
    onSuccess: (result) => {
      queryClient.setQueryData(peopleKey(sheet), result.people);
      setText('');
    },
  });
  const send = useSubmitOnce(importing);

  const submit = (e: FormEvent) => {
    e.preventDefault();
    send(text);
  };

  return (
    <form onSubmit={submit}>
      <label>
        Import people (name,grade,terms,contact per line)
        <br />
        <textarea
          data-testid="import-people"
          rows={4}
          cols={50}
          value={text}
          onChange={(e) => {
            setText(e.target.value);
            importing.reset();
          }}
        />
      </label>
      <br />
      <button type="submit" data-testid="import-submit" disabled={importing.isPending}>
        Import people
      </button>
      {importing.isSuccess && (
        <>
          {' '}Added <strong data-testid="import-added">{importing.data.added}</strong>, updated{' '}
          <strong data-testid="import-updated">{importing.data.updated}</strong>
        </>
      )}
      {importing.isError && (
        <span data-testid="import-error" role="alert">
          {' '}Nothing was imported: every line needs a name (a person on the sheet, by name or alias, or a new name not
          in use), naming no one twice, a grade of A, B or C, terms of whole days or blank, and a contact not another
          person's nor repeated.
        </span>
      )}
    </form>
  );
}

export const contribution = SheetPanels.fill({ order: 11.5, Component: ImportPeople });

